mapper.sql:
FROM order_issue_report i JOIN rental_order o ON o.id=i.rental_order_id
JOIN admin_case_relation l ON l.relation_type='order_issue_report' AND l.relation_id=i.id AND l.is_primary=1
JOIN admin_case c ON c.id=l.admin_case_id AND c.rental_order_id=i.rental_order_id

  AND i.id=#{filter.id}
  AND o.id=#{filter.orderId}
  AND i.reporter_user_id=#{filter.buyer} AND o.buyer_user_id=#{filter.buyer}
  AND i.issue_status=#{filter.status}

mapper.select:
SELECT issue_report_id issue_id,rental_order_item_id item_id,issue_type,affected_quantity quantity,item_summary description
FROM order_issue_item WHERE issue_report_id IN #{id}
ORDER BY issue_report_id,created_at,id
